# Expected values generated by test/scipy/gen_signal_more2.py (scipy 1.18.1).
# max_len_seq, firwin_2d, gammatone, find_peaks_cwt, envelope.
import numpy as np
import scipy.signal as ss
import signal_more2_expected as X

def close(x, ref, rtol: float = 1e-8, atol: float = 1e-10) -> bool:
    a = np.asarray(x, float).ravel()
    if a.shape[0] != len(ref):
        print('size', a.shape[0], len(ref))
        return False
    ok = True
    for i in range(len(ref)):
        if abs(a[i] - ref[i]) > atol + rtol * abs(ref[i]):
            print('mismatch', i, a[i], ref[i])
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def test_mls():
    s, st = ss.max_len_seq(5)
    check(close(s, X.mls5) and close(st, X.mls5_st), 'mls5')
    s, st = ss.max_len_seq(4, state=[1, 0, 1, 1], length=20)
    check(close(s, X.mls4) and close(st, X.mls4_st), 'mls4')
    s, st = ss.max_len_seq(6, taps=[6, 5, 2, 1], length=30)
    check(close(s, X.mls6) and close(st, X.mls6_st), 'mls6')

def test_fir_gammatone():
    check(close(ss.firwin_2d((5, 7), ('hamming', 'hann'), fc=0.4), X.fw2d), 'firwin_2d')
    check(close(ss.firwin_2d((5, 7), 'hamming', fc=0.4, circular=True), X.fw2dc), 'firwin_2d circular')
    b, a = ss.gammatone(440.0, 'fir', fs=16000.0)
    check(close(b, X.gtf_b, 1e-9, 1e-12) and close(a, X.gtf_a), 'gammatone fir')
    b, a = ss.gammatone(440.0, 'fir', order=3, numtaps=20, fs=8000.0)
    check(close(b, X.gtf2_b, 1e-9, 1e-12), 'gammatone fir order')
    b, a = ss.gammatone(440.0, 'iir', fs=16000.0)
    check(close(b, X.gti_b, 1e-9, 1e-30) and close(a, X.gti_a, 1e-9, 1e-12), 'gammatone iir')

def test_cwt_env():
    t = np.linspace(0, 1, 400, endpoint=False)
    sig = np.sin(2 * np.pi * 7 * t) + 0.5 * np.sin(2 * np.pi * 21 * t) + 0.3 * np.cos(2 * np.pi * 3 * t)
    x = np.zeros(200)
    for c, w in [(30, 3.0), (80, 5.0), (140, 4.0)]:
        x += np.exp(-0.5 * ((np.arange(200) - c) / w) ** 2)
    x += 0.02 * np.sin(np.arange(200) * 1.7)
    check(close(ss.find_peaks_cwt(x, np.arange(1, 10)), X.cwt1), 'find_peaks_cwt')
    check(close(ss.find_peaks_cwt(x, np.arange(2, 12, 2), min_snr=0.5), X.cwt2), 'find_peaks_cwt 2')
    check(close(ss.envelope(sig).ravel(), X.env, 1e-8, 1e-9), 'envelope')
    check(close(ss.envelope(sig, squared=True, residual=None), X.env_sq, 1e-8, 1e-9), 'envelope squared')
    check(close(ss.envelope(sig, bp_in=(3, 30)).ravel(), X.env_bp, 1e-8, 1e-9), 'envelope bp')
    check(close(ss.envelope(sig[:100], n_out=50).ravel(), X.env_nout, 1e-8, 1e-9), 'envelope n_out')
    check(close(ss.envelope(sig[:101], residual='all').ravel(), X.env_all, 1e-8, 1e-9), 'envelope all')

test_mls()
test_fir_gammatone()
test_cwt_env()
print('signal more2 OK')
